import numpy as np
from collections import deque

atoms=[]; bonds=[]
def add(el,pos,bonded=()):
    i=len(atoms); atoms.append([el,np.array(pos,float)])
    for b in bonded: bonds.append((i,b))
    return i
def P_(i): return atoms[i][1]
def u(v):
    v=np.array(v,float); return v/np.linalg.norm(v)
def tetra3(w1,phase=0.0):
    w1=u(w1); t=np.array([0.,0.,1.])
    if abs(np.dot(w1,t))>0.9: t=np.array([1.,0.,0.])
    a=u(np.cross(w1,t)); b=np.cross(w1,a); out=[]
    for al in (phase,phase+120.,phase+240.):
        out.append(u(-w1/3.0+(2*np.sqrt(2)/3.0)*(np.cos(np.radians(al))*a+np.sin(np.radians(al))*b)))
    return out
def rot_about(pivot,axis,ang,idxs):
    axis=u(axis); a=np.radians(ang); c,s=np.cos(a),np.sin(a)
    for i in idxs:
