    while q:
        x=q.popleft()
        if d[x]>=cut: continue
        for y in adj[x]:
            if y not in d: d[y]=d[x]+1; q.append(y)
    return d

# ===== core =====
Ge=np.array([0.,0.,0.]); Rh=np.array([2.45,0.,0.]); N=np.array([0.433,1.85,0.]); P=np.array([2.100,2.273,0.])
iGe=add('Ge',Ge); iRh=add('Rh',Rh,bonded=(iGe,)); iN=add('N',N,bonded=(iGe,)); iP=add('P',P,bonded=(iN,iRh)); z=np.array([0.,0.,1.])
u1,u2=u(N-Ge),u(Rh-Ge); bG=-u(u1+u2)
cb,sb=np.cos(np.radians(50)),np.sin(np.radians(50))
add('Cl',Ge+2.20*(cb*bG+sb*z),bonded=(iGe,)); add('Cl',Ge+2.20*(cb*bG-sb*z),bonded=(iGe,))
add('Cl',Rh+2.40*z,bonded=(iRh,))
uCp=-u(u(Ge-Rh)+u(P-Rh)+z); C0=Rh+1.90*uCp
t=z.copy()
if abs(np.dot(uCp,t))>0.9: t=np.array([1.,0.,0.])
e1=u(np.cross(t,uCp)); e2=np.cross(uCp,e1)
cpIdx=[]; methyls=[]
for i in range(5):
    phi=2*np.pi*i/5; rad=np.cos(phi)*e1+np.sin(phi)*e2
    cC=C0+1.208*rad; iC=add('C',cC,bonded=(iRh,)); cpIdx.append(iC)
    iMe=add('C',cC+1.50*rad,bonded=(iC,)); cpIdx.append(iMe); methyls.append((iMe,iC))
# ===== N-aryl =====
u1,u2=u(Ge-N),u(P-N); u3=-u(u1+u2)
C1=N+1.42*u3; e1a=u3; e2a0=u(np.cross(z,e1a))
def aryl_geom(tw):
    e2=np.cos(np.radians(tw))*e2a0+np.sin(np.radians(tw))*np.cross(e1a,e2a0)
    ctr=C1+1.39*e1a; out=[]
    for i in range(6):
        phi=np.radians(180+60*i); rad=np.cos(phi)*e1a+np.sin(phi)*e2
        out.append((ctr+1.39*rad,rad))
    return out
ring=aryl_geom(20.0)
arIdx=[add('C',p,bonded=(iN,) if i==0 else ()) for i,(p,r) in enumerate(ring)]
for a,b in zip(arIdx,arIdx[1:]+arIdx[:1]): bonds.append((a,b))
for i in (2,3,4): add('H',ring[i][0]+1.09*ring[i][1],bonded=(arIdx[i],))
iPrCH=[]
for i in (1,5):
    p,r=ring[i]; iPrCH.append((add('C',p+1.50*r,bonded=(arIdx[i],)), arIdx[i]))
# ===== P phenyls (tetrahedral complements) =====
u1,u2=u(N-P),u(Rh-P); m=u(u1+u2); n_=u(u1-u2); w_=np.cross(m,n_)
s_=np.linalg.norm(u1+u2); alpha=-2/(3*s_); gamma=np.sqrt(1-alpha*alpha)
phTors=[]
for sgn in (1,-1):
    d=alpha*m+sgn*gamma*w_
    c1=P_+1.83*d; iP1=add('C',c1,bonded=(iP,))
    nn=np.array([1.,0.,0.])
    if abs(np.dot(u(nn),d))>0.9: nn=np.array([0.,1.,0.])
    e2=u(np.cross(nn,d)); ctr=c1+1.39*d
    idxs=[iP1]
