    for i in range(1,6):
        phi=np.radians(180+60*i); rad=np.cos(phi)*d+np.sin(phi)*e2
        iC=add('C',ctr+1.39*rad,bonded=(prev,)); idxs.append(iC); prev=iC
    bonds.append((idxs[-1],iP1))
    for iC in idxs[1:]: add('H',atoms[iC][1]+1.09*u(atoms[iC][1]-ctr),bonded=(iC,)); idxs.append(len(atoms)-1)
    phTors.append((iP1,d,idxs))
# ===== iPr methyls =====
iPrTors=[]
for iCH,iAr in iPrCH:
    w=u(P_(iCH)-P_(iAr))
