    iPrTors.append((iCH,w,grp))
# ===== methyl Hs =====
meTors=[]
for iMe,par in methyls:
    w=u(P_(iMe)-P_(par)); grp=[]
    for h in tetra3(w,0.0): grp.append(add('H',P_(iMe)+1.09*h,bonded=(iMe,)))
    meTors.append((iMe,w,grp))
rebuild_adj()
print("atoms",len(atoms))

# ===== torsion refinement =====
tors=[]
tors.append((iN,u3,arIdx+[i for i in range(len(atoms)) if False]))  # placeholder replaced below
tors=[]
# aryl group members: arIdx + everything bonded downstream (iPr etc.)
def downstream(root, pivot_bond):
    seen={root}; q=deque([root])
    while q:
        x=q.popleft()
        for y in adj[x]:
            if y not in seen and (x,y)!=(root,pivot_bond) and (y,x)!=(pivot_bond,root):
                seen.add(y); q.append(y)
    return seen
ar_members=downstream(arIdx[0], iN)
tors.append((iN,u3,sorted(ar_members)))
for iCH,w,grp in iPrTors:
    memb=downstream(iCH,iCH)  # includes CH itself; rotate CH too? CH H and methyls rotate; CH on axis anyway
    tors.append((iCH,w,sorted(memb)))
for iP1,d,idxs in phTors:
    tors.append((iP1,d,sorted(downstream(iP1,iP))))
tors.append((iRh,uCp,sorted(cpIdx)))
for iMe,w,grp in meTors:
    tors.append((iMe,w,grp))

def score(members):
    mset=set(members); md=1e9
    for i in mset:
        di=gdists(i,4)
        for j in range(len(atoms)):
            if j in mset: continue
            if di.get(j,99)<=3: continue
            md=min(md,np.linalg.norm(atoms[i][1]-atoms[j][1]))
    return md
for rnd in range(4):
    for pivot,axis,members in tors:
        best=(score(members),0.0)
        for ang in range(0,360,10):
            rot_about(P_(pivot),axis,ang,members)
            sc=score(members)
            rot_about(P_(pivot),axis,-ang,members)
            if sc>best[0]: best=(sc,ang)
        if best[1]: rot_about(P_(pivot),axis,best[1],members)
    print("round",rnd,"global min nonbonded:",round(min(score(m) for _,_,m in tors),2))

with open('initial.xyz','w') as f:
    f.write(f"{len(atoms)}\ninitial guess Ge-Rh phosphinoamide complex\n")
    for el,p in atoms: f.write(f"{el} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n")
from collections import Counter
print(dict(Counter(el for el,_ in atoms)))
